solutions.naive:
class Solution:
    def fullBloomFlowers(self, flowers: list[list[int]], people: list[int]) -> list[int]:
        ans = []
        for t in people:
            count = 0
            for s, e in flowers:
                if s <= t <= e:
                    count += 1
            ans.append(count)
        return ans

solutions.better:
class Solution:
    def fullBloomFlowers(self, flowers: list[list[int]], people: list[int]) -> list[int]:
        events = []
        for s, e in flowers:
            events.append((s, 0, -1))
            events.append((e, 2, -1))
        for i, t in enumerate(people):
            events.append((t, 1, i))
        events.sort()
        ans = [0] * len(people)
        active = 0
        for _, kind, idx in events:
            if kind == 0:
                active += 1
            elif kind == 1:
                ans[idx] = active
            else:
                active -= 1
        return ans

solutions.optimal:
class Solution:
    def fullBloomFlowers(self, flowers: list[list[int]], people: list[int]) -> list[int]:
        from bisect import bisect_right, bisect_left
        starts = sorted(s for s, _ in flowers)
        ends = sorted(e for _, e in flowers)
        ans = []
        for t in people:
            ans.append(bisect_right(starts, t) - bisect_left(ends, t))
        return ans

